from collections import deque
def comps(g,v=4):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]==v and not seen[r][c]:
                q=deque([(r,c)]); seen[r][c]=True; d=[]
                while q:
                    y,x=q.popleft(); d.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==v and not seen[ny][nx]:
                            seen[ny][nx]=True; q.append((ny,nx))
                out.append(d)
    return out
